<?php

declare(strict_types=1);

use PhpStats\Polyfill\Internal\Dense;
use PhpStats\Polyfill\Internal\RustSort;
use PhpStats\Polyfill\Internal\Svd;
use PhpStats\Polyfill\Internal\SymmetricEigen;

// Bit-for-bit checks of the nalgebra 0.35.0 ports against nalgebra-reference.json,
// generated by tests/reference/nalgebra on aarch64. Floats there are IEEE-754 bit
// patterns in hex; matrices are column-major.

function denseFloat(string $hex): float
{
    return unpack('E', hex2bin($hex))[1];
}

function denseHex(float $x): string
{
    return bin2hex(pack('E', $x));
}

/** @return list<list<float>> */
function denseColumns(array $flat, int $rows, int $cols): array
{
    $values = array_map(denseFloat(...), $flat);
    $columns = [];
    for ($j = 0; $j < $cols; $j++) {
        $columns[$j] = array_slice($values, $j * $rows, $rows);
    }

    return $columns;
}

/** Hex of every entry of a column-major matrix, for exact comparison. */
function denseBits(array $columns): array
{
    return array_map(denseHex(...), $columns === [] ? [] : array_merge(...$columns));
}

/**
 * The SVD calls the C library's hypot(), as Rust's f64::hypot does, so its last
 * bits depend on the platform's libm, for the extension as for the polyfill.
 * The fixture was generated on macOS/aarch64; elsewhere the SVD checks allow
 * rounding-level differences (1e-12 of the largest magnitude).
 */
function denseExactPlatform(): bool
{
    return PHP_OS_FAMILY === 'Darwin' && php_uname('m') === 'arm64';
}

function denseExpectClose(?array $actual, ?array $expected, string $label): void
{
    if (denseExactPlatform() || $expected === null || $actual === null) {
        expect($actual)->toBe($expected, $label);

        return;
    }
    $want = array_map(denseFloat(...), $expected);
    $got = array_map(denseFloat(...), $actual);
    expect(count($got))->toBe(count($want), $label);
    $scale = 0.0;
    foreach ($want as $v) {
        $scale = is_finite($v) ? max($scale, abs($v)) : $scale;
    }
    foreach ($want as $i => $v) {
        if (is_nan($v) || is_infinite($v)) {
            expect(denseHex($got[$i]))->toBe($expected[$i], $label);
        } else {
            expect(abs($got[$i] - $v))->toBeLessThanOrEqual(1e-12 * max($scale, PHP_FLOAT_MIN), $label);
        }
    }
}

$fixture = loadFixture('nalgebra-reference.json');

it('reproduces SVD::new singular values and vectors', function () use ($fixture) {
    foreach ($fixture['svd'] as $n => $case) {
        $label = "svd #$n {$case['rows']}x{$case['cols']}";
        $svd = new Svd(denseColumns($case['a'], $case['rows'], $case['cols']), $case['u'], $case['v']);
        denseExpectClose(array_map(denseHex(...), $svd->singularValues), $case['s'], $label);
        if (denseExactPlatform()) {
            expect($svd->u === null ? null : denseBits($svd->u))->toBe($case['U'], "$label U");
            expect($svd->vT === null ? null : denseBits($svd->vT))->toBe($case['Vt'], "$label V^T");
        } else {
            expect($svd->u === null)->toBe($case['U'] === null, "$label U")
                ->and($svd->vT === null)->toBe($case['Vt'] === null, "$label V^T");
        }
    }
});

it('reproduces SVD::solve', function () use ($fixture) {
    foreach ($fixture['solve'] as $n => $case) {
        $svd = new Svd(denseColumns($case['a'], $case['rows'], $case['cols']), true, true);
        $x = $svd->solve(denseColumns($case['b'], $case['rows'], $case['bcols']), denseFloat($case['eps']));
        if (denseExactPlatform()) {
            expect(denseBits($x))->toBe($case['x'], "solve #$n");
        } else {
            expect(count(denseBits($x)))->toBe(count($case['x']), "solve #$n");
        }
    }
});

it('reproduces SymmetricEigen::new, including the Gauss-Hermite Jacobi matrices', function () use ($fixture) {
    foreach ($fixture['eigen'] as $n => $case) {
        $eigen = new SymmetricEigen(denseColumns($case['a'], $case['n'], $case['n']));
        expect(array_map(denseHex(...), $eigen->eigenvalues))->toBe($case['values'], "eigen #$n values");
        expect(denseBits($eigen->eigenvectors))->toBe($case['vectors'], "eigen #$n vectors");
    }
});

it('reproduces matrix products on both sides of the gemm dispatch', function () use ($fixture) {
    foreach ($fixture['mul'] as $n => $case) {
        $a = denseColumns($case['a'], $case['ar'], $case['ac']);
        $b = denseColumns($case['b'], $case['br'], $case['bc']);
        $c = match ($case['op']) {
            'mul' => Dense::multiply($a, $b, $case['ar']),
            'mul_bt' => Dense::multiply($a, Dense::transpose($b, $case['br']), $case['ar']),
            'tr_mul' => Dense::transposeMultiply($a, $b),
            'mul_vec' => [Dense::multiplyVector($a, $b[0], $case['ar'])],
            'tr_mul_vec' => [Dense::transposeMultiplyVector($a, $b[0])],
        };
        expect(denseBits($c))->toBe($case['c'], "mul #$n {$case['op']} {$case['ar']}x{$case['ac']} by {$case['br']}x{$case['bc']}");
    }
});

it('reproduces norm and norm_squared', function () use ($fixture) {
    foreach ($fixture['norm'] as $n => $case) {
        $a = denseColumns($case['a'], $case['rows'], $case['cols']);
        $v = array_map(denseFloat(...), $case['a']);
        expect([
            denseHex(Dense::normSquared($a)),
            denseHex(Dense::norm($a)),
            denseHex(Dense::vectorNormSquared($v)),
            denseHex(Dense::vectorNorm($v)),
        ])->toBe([$case['norm_squared'], $case['norm'], $case['vector_norm_squared'], $case['vector_norm']], "norm #$n");
    }
});

it('matches Rust hypot and the hardware fused multiply-add', function () use ($fixture) {
    foreach ($fixture['hypot'] as $n => [$x, $y, $h]) {
        expect(denseHex(hypot(denseFloat($x), denseFloat($y))))->toBe($h, "hypot #$n");
    }
    foreach ($fixture['fma'] as $n => [$a, $b, $c, $r]) {
        expect(denseHex(Dense::fma(denseFloat($a), denseFloat($b), denseFloat($c))))->toBe($r, "fma #$n");
    }
});

it('keeps an underflowed product sign in the fused kernel', function () {
    expect(denseHex(Dense::fma(-1e-200, 1e-200, 0.0)))->toBe('8000000000000000')
        ->and(denseHex(Dense::fma(1e-200, 1e-200, -0.0)))->toBe('0000000000000000')
        // a * b overflows, but the fused sum is finite (Rust's mul_add gives these bits).
        ->and(denseHex(Dense::fma(2.0 ** 512, 1.5 * 2.0 ** 512, -PHP_FLOAT_MAX)))->toBe('7fe0000000000001');
});

it('orders ties as Rust sort_unstable_by does', function () {
    // 40 values with ties take ipnsort's quicksort; Rust 1.99 gives this permutation.
    $values = [];
    for ($i = 0; $i < 40; $i++) {
        $values[] = [(float) (($i * 7) % 3), $i];
    }
    $sorted = RustSort::sortUnstableBy($values, fn (array $x, array $y): bool => $y[0] < $x[0]);
    expect(array_column($sorted, 1))->toBe([
        20, 2, 5, 8, 11, 14, 23, 26, 29, 32, 35, 38, 17, 13, 16, 1, 19, 22, 7, 25,
        4, 28, 31, 10, 34, 37, 6, 15, 18, 0, 21, 24, 27, 9, 30, 33, 3, 36, 12, 39,
    ]);
});

it('mirrors nalgebra on degenerate input', function () {
    expect((new Svd([[NAN]], true, true))->singularValues[0])->toBeNan()
        ->and(thrownCode(fn () => new Svd([[1.0, NAN], [2.0, 3.0]], true, true)))->not->toBeNull()
        ->and(thrownCode(fn () => new Svd([], true, true)))->not->toBeNull()
        ->and((new Svd([[0.0, 0.0], [0.0, 0.0]], true, true))->singularValues)->toBe([0.0, 0.0])
        ->and(thrownCode(fn () => (new Svd([[1.0]], true, true))->solve([[1.0]], -1.0)))->not->toBeNull();
});
